  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="content"][data-tone="accent"][data-starting-style]) {
    --_rich-tooltip-content-scale: 95% 95%;
    scale: var(--_rich-tooltip-content-scale);
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="content"][data-tone="accent"][data-ending-style]) {
    --_rich-tooltip-content-scale: 95% 95%;
    scale: var(--_rich-tooltip-content-scale);
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="previous"]),
  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="next"]),
  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="close"]) {
    block-size: calc(var(--spacing) * 7);
    min-inline-size: calc(var(--spacing) * 7);
    margin-inline-end: calc(var(--spacing) * -1);
    gap: calc(var(--spacing) * 1);
    padding-inline: calc(var(--spacing) * 2);
    border-radius: var(--cui-rich-tooltip-action-radius);
    background: var(--cui-rich-tooltip-action-background);
    color: var(--cui-rich-tooltip-action-foreground);
    font-size: var(--text-label);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="previous"][data-icon-only="true"]),
  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="next"][data-icon-only="true"]),
  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="close"][data-icon-only="true"]) {
    inline-size: calc(var(--spacing) * 7);
    padding-inline: 0;
  }

  @media (hover: hover) {
    :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="previous"]:hover:not(:disabled)),
    :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="next"]:hover:not(:disabled)),
    :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="close"]:hover:not(:disabled)) {
      background: oklch(from currentColor l c h / 0.15);
    }
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="previous"]:disabled),
  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="next"]:disabled),
  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="close"]:disabled) {
    opacity: var(--disabled-opacity);
  }
}

